// Writes public/styles/light.json and dark.json from the app's own outdoor map style
// (../Switchback/Resources/switchback-style*.json, generated by ../scripts/make-style.py).
// The iPhone app draws the point-of-interest icons ("sb-…") itself at runtime; the website has no such
// pictures, so icon layers are dropped or reduced to their text. The peak labels come in two layers
// (feet and metres): both are kept, and the site shows the one matching the units setting.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, '..', 'public', 'styles');
mkdirSync(out, { recursive: true });

for (const [from, to] of [['switchback-style.json', 'light.json'], ['switchback-style-dark.json', 'dark.json']]) {
  const style = JSON.parse(readFileSync(join(here, '..', '..', 'Switchback', 'Resources', from), 'utf8'));
  const layers = [];
  for (const layer of style.layers) {
    const layout = layer.layout;
    if (layout && 'icon-image' in layout) {
      if (!('text-field' in layout)) continue; // an icon and nothing else
      for (const key of Object.keys(layout)) if (key.startsWith('icon-')) delete layout[key];
      delete layout['text-optional'];
      if (layout['text-anchor'] === 'top') { delete layout['text-anchor']; delete layout['text-offset']; }
      if (layer.paint) for (const key of Object.keys(layer.paint)) if (key.startsWith('icon-')) delete layer.paint[key];
      // point-of-interest names without their icons are clutter until you are close
      if (layer.id === 'poi') layer.minzoom = Math.max(layer.minzoom ?? 0, 15);
    }
    layers.push(layer);
  }
  style.layers = layers;
  delete style.sprite;
  writeFileSync(join(out, to), JSON.stringify(style));
  console.log(`styles/${to}: ${layers.length} layers`);
}
